import React, { useState } from 'react';
import { Menu, Search, RefreshCw, Brain, TrendingUp } from 'lucide-react';

const Header = ({ onMenuClick, onRefresh, selectedCategory, setSelectedCategory }) => {
  const [searchQuery, setSearchQuery] = useState('');

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      window.location.href = `/search?q=${encodeURIComponent(searchQuery.trim())}`;
    }
  };

  const handleRefresh = () => {
    onRefresh();
  };

  return (
    <header className="fixed top-0 left-0 right-0 bg-white shadow-sm border-b border-gray-200 z-30">
      <div className="flex items-center justify-between px-4 py-3">
        {/* 左侧：菜单 + Logo */}
        <div className="flex items-center space-x-4">
          <button
            onClick={onMenuClick}
            className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
            aria-label="打开菜单"
          >
            <Menu className="w-5 h-5" />
          </button>

          <div className="flex items-center space-x-2">
            <Brain className="w-8 h-8 text-blue-600" />
            <div>
              <h1 className="text-xl font-bold text-gray-900">AI资讯平台</h1>
              <p className="text-xs text-gray-500">实时获取AI科技资讯</p>
            </div>
          </div>
        </div>

        {/* 中间：分类导航 */}
        <div className="hidden md:flex items-center space-x-1">
          {[
            '全部', 'AI新闻', 'AI框架', '新算法', '新思路', '新工具'
          ].map((category) => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                selectedCategory === category
                  ? 'bg-blue-100 text-blue-700'
                  : 'text-gray-600 hover:bg-gray-100'
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* 右侧：搜索 + 刷新 */}
        <div className="flex items-center space-x-3">
          {/* 搜索框 */}
          <form onSubmit={handleSearch} className="hidden sm:flex items-center">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
              <input
                type="text"
                placeholder="搜索AI资讯..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none w-64"
              />
            </div>
          </form>

          {/* 刷新按钮 */}
          <button
            onClick={handleRefresh}
            className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
            aria-label="刷新内容"
          >
            <RefreshCw className="w-5 h-5" />
          </button>

          {/* 分析页面链接 */}
          <a
            href="/analytics"
            className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
            aria-label="数据分析"
          >
            <TrendingUp className="w-5 h-5" />
          </a>
        </div>
      </div>
    </header>
  );
};

export default Header;
